import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int[][] g = new int[n][m];
        List<int[]> q = new ArrayList<>();
        int left = 0;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < m; c++) {
                g[r][c] = nextInt();
                if (g[r][c] == 2) q.add(new int[] {r, c});
                if (g[r][c] == 1) left++;
            }
        // Each BFS layer is one second; all infected cells start together.
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        int t = 0;
        while (!q.isEmpty() && left > 0) {
            List<int[]> next = new ArrayList<>();
            for (int[] cell : q)
                for (int d = 0; d < 4; d++) {
                    int x = cell[0] + dr[d], y = cell[1] + dc[d];
                    if (0 <= x && x < n && 0 <= y && y < m && g[x][y] == 1) {
                        g[x][y] = 2;
                        left--;
                        next.add(new int[] {x, y});
                    }
                }
            q = next;
            t++;
        }
        System.out.println(left == 0 ? t : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	g := make([][]int64, n)
	var q [][2]int
	left := 0
	for r := range g {
		g[r] = make([]int64, m)
		for c := range g[r] {
			g[r][c] = nextInt()
			if g[r][c] == 2 {
				q = append(q, [2]int{r, c})
			}
			if g[r][c] == 1 {
				left++
			}
		}
	}
	// Each BFS layer is one second; all infected cells start together.
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	t := 0
	for len(q) > 0 && left > 0 {
		var next [][2]int
		for _, cell := range q {
			for _, d := range dirs {
				x, y := cell[0]+d[0], cell[1]+d[1]
				if 0 <= x && x < n && 0 <= y && y < m && g[x][y] == 1 {
					g[x][y] = 2
					left--
					next = append(next, [2]int{x, y})
				}
			}
		}
		q = next
		t++
	}
	if left == 0 {
		fmt.Println(t)
	} else {
		fmt.Println(-1)
	}
}
